// `WorktreeCreate`: a git worktree from `HEAD`, with the files that `.worktreeinclude` names.
// A `WorktreeCreate` hook replaces the creation of Claude Code, so the copy of `.worktreeinclude` is done here.

import fs from "node:fs";
import path from "node:path";
import {
  BRANCH_PREFIX,
  branchOf,
  INCLUDE_FILE,
  inside,
  validName,
  WORKTREE_DIR,
  type WorktreePayload,
} from "../domain/worktree.ts";
import { NAME_INVALID, NOT_IN_REPO } from "../prompts.ts";
import { hashOf, writeCopied } from "./copied.ts";
import { git, includedFiles, mainRoot } from "./git.ts";

/** Copies the files that `.worktreeinclude` of `root` names into `dest`. A file that exists in `dest` stays. Gives the hash of each copy by path. */
export const copyIncluded = async (
  root: string,
  dest: string,
): Promise<Record<string, string>> => {
  const include = path.join(root, INCLUDE_FILE);
  const copied: Record<string, string> = {};
  if (!fs.existsSync(include)) return copied;
  for (const rel of includedFiles(root, include)) {
    const to = path.join(dest, rel);
    if (!inside(rel) || fs.existsSync(to)) continue;
    fs.mkdirSync(path.dirname(to), { recursive: true });
    fs.cpSync(path.join(root, rel), to, { dereference: false });
    const hash = await hashOf(to);
    if (hash) copied[rel] = hash;
  }
  return copied;
};

/** The result of the hook: the path for stdout, or the text for stderr. `made` is the repository root when this call made the worktree. */
export type Created = { path: string; made?: string } | { error: string };

/** Creates the worktree `name` of the repository that holds `cwd`. The branch starts at `HEAD`. */
export const create = async ({
  name,
  cwd,
}: WorktreePayload): Promise<Created> => {
  if (!validName(name)) return { error: NAME_INVALID({ name: String(name) }) };
  const root = mainRoot(cwd ?? process.cwd());
  if (!root) return { error: NOT_IN_REPO };
  const dest = path.join(root, WORKTREE_DIR, name);
  if (
    git(dest, ["rev-parse", "--is-inside-work-tree"]).ok &&
    fs.existsSync(dest)
  )
    return { path: dest };
  const added = git(root, [
    "worktree",
    "add",
    "-b",
    branchOf(name),
    dest,
    "HEAD",
  ]);
  if (!added.ok)
    return {
      error: `git worktree add failed (a branch ${BRANCH_PREFIX}${name} may exist): ${added.err.trim()}`,
    };
  await writeCopied(dest, await copyIncluded(root, dest));
  return { path: dest, made: root };
};
